/// <summary>
/// One response shape for every operation of HSMobileOpsOrderCreateService.
/// </summary>
[DataContractAttribute]
class HSMobileOpsOrderResponse
{
    boolean success;
    str errorCode;
    str message;
    str documentNumber;
    boolean alreadyCreated;
    str transitWarehouseId;
    str currencyCode;
    real orderTotal;
    boolean hasMore;
    str confirmationNumber;
    str packingSlipId;
    List reasons;
    List actions;
    List orders;
    HSMobileOpsOrderItem item;
    List vendors;
    List lines;
    List permissions;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

